INSERT INTO periodo(numero,nome,ordem) VALUES(3,'3º período',3) ON CONFLICT(numero) DO NOTHING;
INSERT INTO disciplina(periodo_id,nome,slug,descricao,possui_prova) SELECT id,'Sistemas Digitais','sistemas_digitais','Monitor e prática de IA com os materiais disponíveis. Lista e prova ainda não fornecidas.',TRUE FROM periodo WHERE numero=3 ON CONFLICT(slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,ordem) SELECT id,'Sistemas analógicos e digitais','sistemas_analogicos_e_digitais',1 FROM disciplina WHERE slug='sistemas_digitais' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO material(disciplina_id,assunto_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual) SELECT d.id,a.id,'Sistemas analógicos e digitais','PDF teórico; fonte de conceitos para Monitor e questões de IA.','SLIDE_AULA','local:materiais_academicos/periodo_03/sistemas_digitais/Sistemas analógicos e digitais.pdf',TRUE FROM disciplina d JOIN assunto a ON a.disciplina_id=d.id AND a.slug='sistemas_analogicos_e_digitais' WHERE d.slug='sistemas_digitais' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/sistemas_digitais/Sistemas analógicos e digitais.pdf');
